const SUPABASE_URL = "https://hofmqfujmtmflcjutjvu.supabase.co";
const SUPABASE_PUBLISHABLE_KEY = "sb_publishable_rI6Vi8smNkCuKvUkZyElIg_PFvu1kXE";
let supabaseClient = null;
let promesaSupabase = null;
let authListenerConfigurado = false;
function asegurarSupabase(){
if(supabaseClient) return Promise.resolve(supabaseClient);
if(promesaSupabase) return promesaSupabase;
promesaSupabase = new Promise((resolve, reject) => {
const timeoutSdk = setTimeout(() => {
reject(new Error("Tiempo de espera agotado cargando Supabase."));
}, 15000);
const conectar = () => {
clearTimeout(timeoutSdk);
if(!window.supabase?.createClient){
reject(new Error("No se pudo cargar la librería de Supabase."));
return;
}
supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY);
if(!authListenerConfigurado){
authListenerConfigurado = true;
supabaseClient.auth.onAuthStateChange((event) => {
if(event === "SIGNED_OUT") cerrarAdmin();
});
}
resolve(supabaseClient);
};
if(window.supabase?.createClient){
conectar();
return;
}
const cargarScript = (src, fallback = false) => {
const script = document.createElement("script");
script.src = src;
script.async = true;
script.onload = conectar;
script.onerror = () => {
script.remove();
if(!fallback){
cargarScript("https://unpkg.com/@supabase/supabase-js@2", true);
}else{
clearTimeout(timeoutSdk);
reject(new Error("No se pudo descargar la librería de Supabase."));
}
};
document.head.appendChild(script);
};
cargarScript("https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2");
}).catch(error => {
promesaSupabase = null;
throw error;
});
return promesaSupabase;
}
