function fechaInputLocal(valor){
if(!valor) return "";
const d = new Date(valor);
if(Number.isNaN(d.getTime())) return "";
const pad = n => String(n).padStart(2, "0");
return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}
async function cargarDatosSupabase(modoAdmin = false){
await asegurarSupabase();
const productosSelect = modoAdmin
? "*"
: "id,categoria,nombre,descripcion,precio,disponible,admite_extras,etiqueta,imagen_url";
const extrasSelect = modoAdmin
? "*"
: "id,nombre,precio,disponible";
const promosSelect = modoAdmin
? "*"
: "id,nombre,producto_id,tipo,valor,inicio,fin,activa,created_at";
const consultas = [
supabaseClient.from("productos").select(productosSelect).order("nombre"),
supabaseClient.from("extras").select(extrasSelect).order("nombre"),
supabaseClient.from("promociones").select(promosSelect).order("created_at", { ascending:false })
];
if(modoAdmin){
consultas.push(supabaseClient.from("ventas").select("*").order("fecha", { ascending:false }));
consultas.push(supabaseClient.from("gastos").select("*").order("fecha", { ascending:false }));
}
const resultados = await Promise.all(consultas);
const [productosRes, extrasRes, promosRes, ventasRes, gastosRes] = resultados;
for(const r of resultados){
if(r.error) throw r.error;
}
PRODUCTOS = (productosRes.data || []).map(p => ({
id: String(p.id),
categoria: p.categoria,
nombre: p.nombre,
descripcion: p.descripcion || "",
precio: Number(p.precio) || 0,
costo: modoAdmin ? (Number(p.costo) || 0) : 0,
disponible: p.disponible !== false,
admiteExtras: !!p.admite_extras,
etiqueta: p.etiqueta || "",
imagenUrl: p.imagen_url || ""
}));
EXTRAS = (extrasRes.data || []).map(e => ({
id: String(e.id),
nombre: String(e.nombre || "").trim(),
precio: Number(e.precio) || 0,
costo: modoAdmin ? (Number(e.costo) || 0) : 0,
disponible: e.disponible !== false
}));
PROMOS = (promosRes.data || []).map(pr => ({
id: String(pr.id),
nombre: pr.nombre || "",
productoId: pr.producto_id || "todos",
tipo: pr.tipo || "monto",
valor: Number(pr.valor) || 0,
inicio: fechaInputLocal(pr.inicio),
fin: fechaInputLocal(pr.fin),
activa: !!pr.activa
}));
if(modoAdmin){
VENTAS = ((ventasRes && ventasRes.data) || []).map(v => ({
id: String(v.id),
fecha: v.fecha,
items: Array.isArray(v.items) ? v.items : [],
total: Number(v.total) || 0,
costoTotal: Number(v.costo_total) || 0,
utilidad: Number(v.utilidad) || 0
}));
GASTOS = ((gastosRes && gastosRes.data) || []).map(g => ({
id: String(g.id),
fecha: g.fecha,
categoria: g.categoria || "Otros",
descripcion: g.descripcion || "",
monto: Number(g.monto) || 0,
proveedor: g.proveedor || "",
formaPago: g.forma_pago || "",
nota: g.nota || ""
}));
}
supabaseListo = true;
}
