/* ============================================================
3. ESTADO DEL CARRITO
Cada línea del carrito es un producto + su combinación de extras.
"La Clásica sola" y "La Clásica con bacon" son líneas distintas.
carrito = { claveDeLinea: {productoId, extrasIds, cantidad} }
============================================================ */
let carrito = {};
let entregaSeleccionada = "entrega";
let seleccionExtras = {}; // { productoId: [extraId, ...] } — lo que está marcado en cada tarjeta ahora mismo
const money = n => "₡" + Math.round(n).toLocaleString("es-CR");
const idNuevo = prefijo => prefijo + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2,6);
/* ============================================================
4. PROMOCIONES — lógica de vigencia y precio
============================================================ */
function estadoPromo(promo){
if(!promo.activa) return "pausada";
const ahora = new Date();
const inicio = promo.inicio ? new Date(promo.inicio) : null;
const fin = promo.fin ? new Date(promo.fin) : null;
if(fin && ahora > fin) return "expirada";
if(inicio && ahora < inicio) return "programada";
return "vigente";
}
function promoParaProducto(id){
return PROMOS.find(pr =>
(String(pr.productoId) === String(id) || pr.productoId === "todos") &&
estadoPromo(pr) === "vigente"
);
}
function precioVigente(p){
const promo = promoParaProducto(p.id);
if(!promo) return { precio: p.precio, original: null, promo: null };
const nuevo = promo.tipo === "precio" ? promo.valor : Math.max(0, p.precio - promo.valor);
return { precio: nuevo, original: p.precio, promo };
}
/* ============================================================
5. EXTRAS — ayudantes
============================================================ */
function extrasDisponibles(){
return EXTRAS.filter(e =>
e.disponible !== false &&
String(e.nombre || "").trim().length > 0
);
}
async function recargarExtrasDesdeSupabase(){
await asegurarSupabase();
const { data, error } = await supabaseClient
.from("extras")
.select("id,nombre,precio,costo,disponible")
.order("nombre");
if(error) throw error;
EXTRAS = (data || []).map(e => ({
id: String(e.id),
nombre: String(e.nombre ?? "").trim(),
precio: Number(e.precio) || 0,
costo: Number(e.costo) || 0,
disponible: e.disponible !== false
}));
const idsValidos = new Set(EXTRAS.map(e => e.id));
Object.keys(seleccionExtras).forEach(productoId => {
seleccionExtras[productoId] = (seleccionExtras[productoId] || [])
.filter(extraId => idsValidos.has(String(extraId)));
});
}
function extraPorId(id){
return EXTRAS.find(e => e.id === id);
}
function precioExtras(extrasIds){
return (extrasIds || []).reduce((s,id) => { const e = extraPorId(id); return s + (e ? e.precio : 0); }, 0);
}
function costoExtras(extrasIds){
return (extrasIds || []).reduce((s,id) => { const e = extraPorId(id); return s + (e ? e.costo : 0); }, 0);
}
function nombreExtras(extrasIds){
return (extrasIds || []).map(id => { const e = extraPorId(id); return e ? e.nombre : null; }).filter(Boolean);
}
function claveLinea(productoId, extrasIds){
const orden = (extrasIds || []).slice().sort();
return orden.length ? productoId + "::" + orden.join(",") : productoId;
}
function precioLinea(p, extrasIds){
return precioVigente(p).precio + precioExtras(extrasIds);
}
function toggleExtraSeleccion(productoId, extraId, marcado){
if(bloquearPedidoSiCerrado()) return;
if(!seleccionExtras[productoId]) seleccionExtras[productoId] = [];
if(marcado){
if(!seleccionExtras[productoId].includes(extraId)) seleccionExtras[productoId].push(extraId);
}else{
seleccionExtras[productoId] = seleccionExtras[productoId].filter(id => id !== extraId);
}
actualizarControlCantidad(productoId);
}
