renderAdminProductos();
renderAdminExtras();
renderAdminPromos();
renderContabilidad();
try{ await cargarPedidosAdmin(); }catch(error){ console.warn("Pedidos:", error); }
try{ await cargarInventarioAdmin(); }catch(error){ console.warn("Inventario:", error); }
