function rendimientoReceta(lineas){
if(!lineas.length) return null;
const rendimientos=lineas.map(r=>{
const inv=INVENTARIO.find(i=>i.id===r.inventarioId);
if(!inv || r.cantidad<=0) return Infinity;
return Math.floor(inv.stock/r.cantidad);
}).filter(Number.isFinite);
return rendimientos.length ? Math.max(0,Math.min(...rendimientos)) : null;
}
function renderRecetaProductoSeleccionado(){
const root=document.getElementById("receta-producto-lista");
const sel=document.getElementById("receta-producto-select");
if(!root || !sel) return;
const id=String(sel.value||"");
const lineas=RECETAS_PRODUCTO.filter(r=>r.productoId===id);
if(!lineas.length){
root.innerHTML='<div class="recipe-empty">Este producto todavía no tiene ingredientes configurados. No descontará inventario automáticamente.</div>';
return;
}
const rendimiento=rendimientoReceta(lineas);
const resumen=rendimiento===null ? "" : `<div class="recipe-yield">Con el stock actual podés preparar aproximadamente <strong>${rendimiento}</strong> unidades de este producto.</div>`;
root.innerHTML=resumen+lineas.map(r=>{
const inv=INVENTARIO.find(i=>i.id===r.inventarioId);
return `<div class="recipe-row">
<div class="recipe-ing">${escHtml(inv?.nombre||"Insumo eliminado")}</div>
<div class="recipe-qty">${Number(r.cantidad).toLocaleString("es-CR",{maximumFractionDigits:3})} ${escHtml(inv?.unidad||"")}</div>
<button class="a-btn delete recipe-delete" onclick="eliminarLineaReceta('producto','${r.id}')">Eliminar</button>
</div>`;
}).join("");
}
