function abrirRecetaModal(tipo,parentId){
if(!INVENTARIO.length){
mostrarConfirmacion("Primero agregá al menos un insumo al inventario.","error");
return;
}
document.getElementById("receta-tipo").value=tipo;
document.getElementById("receta-parent-id").value=parentId;
document.getElementById("receta-linea-id").value="";
document.getElementById("receta-cantidad").value="";
const sel=document.getElementById("receta-inventario-id");
sel.innerHTML=INVENTARIO.filter(i=>i.activo!==false).map(i=>
`<option value="${escAttr(i.id)}">${escHtml(i.nombre)} · ${escHtml(i.unidad)}</option>`
).join("");
document.getElementById("receta-modal-title").textContent=
tipo==="producto" ? "Agregar ingrediente al producto" : "Agregar ingrediente al extra";
const modal=document.getElementById("receta-modal");
modal.classList.remove("hidden");
modal.setAttribute("aria-hidden","false");
}
function cerrarRecetaModal(){
const modal=document.getElementById("receta-modal");
modal.classList.add("hidden");
modal.setAttribute("aria-hidden","true");
}
async function guardarLineaReceta(){
const tipo=document.getElementById("receta-tipo").value;
const parentId=document.getElementById("receta-parent-id").value;
const inventarioId=document.getElementById("receta-inventario-id").value;
const cantidad=Number(document.getElementById("receta-cantidad").value)||0;
if(cantidad<=0){
mostrarConfirmacion("La cantidad debe ser mayor que cero.","error");
return;
}
try{
if(tipo==="producto"){
const {error}=await supabaseClient.from("recetas_producto").upsert({
producto_id:parentId,
inventario_id:inventarioId,
cantidad
},{onConflict:"producto_id,inventario_id"});
if(error) throw error;
}else{
const {error}=await supabaseClient.from("recetas_extra").upsert({
extra_id:parentId,
inventario_id:inventarioId,
cantidad
},{onConflict:"extra_id,inventario_id"});
if(error) throw error;
}
cerrarRecetaModal();
await cargarInventarioAdmin();
renderInventario();
mostrarConfirmacion("✓ Ingrediente agregado a la receta");
}catch(error){
mostrarConfirmacion("No se pudo guardar la receta: "+(error.message||error),"error");
}
}
async function eliminarLineaReceta(tipo,id){
if(!await confirmarAccion({
titulo:"Eliminar ingrediente",
mensaje:"Este ingrediente dejará de descontarse automáticamente.",
confirmar:"Eliminar",
peligro:true,
icono:"!"
})) return;
try{
const tabla=tipo==="producto"?"recetas_producto":"recetas_extra";
const {error}=await supabaseClient.from(tabla).delete().eq("id",id);
if(error) throw error;
await cargarInventarioAdmin();
renderInventario();
mostrarConfirmacion("✓ Ingrediente eliminado de la receta");
}catch(error){
mostrarConfirmacion("No se pudo eliminar: "+(error.message||error),"error");
}
}
