async function guardarInventarioDesdeModal(){
const id=document.getElementById("inventario-id").value.trim();
const nombre=document.getElementById("inventario-nombre").value.trim();
const categoria=document.getElementById("inventario-categoria").value;
const unidad=document.getElementById("inventario-unidad").value;
const stock=Number(document.getElementById("inventario-stock").value)||0;
const minimo=Number(document.getElementById("inventario-minimo").value)||0;
const costo=Number(document.getElementById("inventario-costo").value)||0;
const proveedor=document.getElementById("inventario-proveedor").value.trim();
const nota=document.getElementById("inventario-nota").value.trim();
if(!nombre){
mostrarConfirmacion("Poné un nombre al insumo.","error");
return;
}
if(stock<0 || minimo<0 || costo<0){
mostrarConfirmacion("Stock, mínimo y costo no pueden ser negativos.","error");
return;
}
const editando=!!id;
if(!await confirmarAccion({
titulo:editando?"Guardar cambios":"Crear insumo",
mensaje:editando?`Se actualizará "${nombre}".`:`Se agregará "${nombre}" al inventario.`,
confirmar:editando?"Guardar":"Crear",
icono:"✓"
})) return;
const payload={
id:editando?id:(crypto.randomUUID?crypto.randomUUID():idNuevo("inv")),
nombre,categoria,unidad,
stock,
stock_minimo:minimo,
costo_unitario:costo,
proveedor:proveedor||null,
nota:nota||null,
activo:true,
updated_at:new Date().toISOString()
};
try{
const {error}=await supabaseClient.from("inventario").upsert(payload);
if(error) throw error;
cerrarInventarioModal();
await cargarInventarioAdmin();
renderInventario();
mostrarConfirmacion(editando?"✓ Insumo actualizado":"✓ Insumo creado");
}catch(error){
mostrarConfirmacion("No se pudo guardar: "+(error.message||error),"error");
}
}
