async function subirImagenSitio(file,tipo,maxLado=1800,calidad=.84){
await asegurarSupabase();
const {data:{session}}=await supabaseClient.auth.getSession();
if(!session) throw new Error("Tu sesión administrativa expiró.");
const blob=await comprimirImagen(file,maxLado,calidad);
const ruta=`${tipo}/${Date.now()}.jpg`;
const {error}=await supabaseClient.storage
.from(STORAGE_BUCKET_SITIO)
.upload(ruta,blob,{contentType:"image/jpeg",cacheControl:"31536000",upsert:false});
if(error) throw error;
const {data}=supabaseClient.storage.from(STORAGE_BUCKET_SITIO).getPublicUrl(ruta);
if(!data?.publicUrl) throw new Error("No se obtuvo la URL pública de la imagen.");
return {url:data.publicUrl,ruta};
}
async function borrarImagenSitioAnterior(url){
if(!url) return;
try{
const marker=`/storage/v1/object/public/${STORAGE_BUCKET_SITIO}/`;
const pos=url.indexOf(marker);
if(pos<0) return;
const ruta=decodeURIComponent(url.slice(pos+marker.length));
await supabaseClient.storage.from(STORAGE_BUCKET_SITIO).remove([ruta]);
}catch(error){
console.warn("No se pudo borrar imagen anterior:",error);
}
}
