const STORAGE_BUCKET_PRODUCTOS = "productos";
function extensionImagen(file){
const tipo = (file.type || "").toLowerCase();
if(tipo.includes("png")) return "png";
if(tipo.includes("webp")) return "webp";
return "jpg";
}
function cargarImagenArchivo(file){
return new Promise((resolve, reject) => {
const img = new Image();
const url = URL.createObjectURL(file);
img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("No se pudo leer la imagen.")); };
img.src = url;
});
}
async function comprimirImagen(file, maxLado = 1400, calidad = 0.82){
if(!file || !file.type.startsWith("image/")) throw new Error("Seleccioná un archivo de imagen válido.");
if(file.size > 25 * 1024 * 1024) throw new Error("La imagen es demasiado grande. Máximo 25 MB antes de comprimir.");
const img = await cargarImagenArchivo(file);
let ancho = img.naturalWidth || img.width;
let alto = img.naturalHeight || img.height;
if(!ancho || !alto) throw new Error("No se pudieron obtener las dimensiones de la imagen.");
const escala = Math.min(1, maxLado / Math.max(ancho, alto));
ancho = Math.max(1, Math.round(ancho * escala));
alto = Math.max(1, Math.round(alto * escala));
const canvas = document.createElement("canvas");
canvas.width = ancho;
canvas.height = alto;
const ctx = canvas.getContext("2d", { alpha:false });
ctx.drawImage(img, 0, 0, ancho, alto);
return await new Promise((resolve, reject) => {
canvas.toBlob(blob => blob ? resolve(blob) : reject(new Error("No se pudo comprimir la imagen.")), "image/jpeg", calidad);
});
}
function rutaStorageDesdeUrl(url){
if(!url) return null;
const marcador = `/storage/v1/object/public/${STORAGE_BUCKET_PRODUCTOS}/`;
const pos = url.indexOf(marcador);
if(pos === -1) return null;
return decodeURIComponent(url.slice(pos + marcador.length).split("?")[0]);
}
async function subirFotoProducto(id, input){
const file = input?.files?.[0];
if(!file) return;
const p = PRODUCTOS.find(x => x.id === id);
if(!p) return;
if(!await confirmarAccion({
titulo:p.imagenUrl ? "Cambiar fotografía" : "Subir fotografía",
mensaje:`La nueva imagen se publicará en "${p.nombre || "este producto"}".`,
confirmar:p.imagenUrl ? "Cambiar foto" : "Subir foto",
icono:"📷"
})){
if(input) input.value = "";
return;
}
const status = document.getElementById("foto-status-" + id);
if(status) status.textContent = "Comprimiendo foto…";
try{
await asegurarSupabase();
const { data:{ session } } = await supabaseClient.auth.getSession();
if(!session) throw new Error("Tu sesión de administrador expiró. Iniciá sesión de nuevo.");
const blob = await comprimirImagen(file);
const rutaAnterior = rutaStorageDesdeUrl(p.imagenUrl);
const ruta = `productos/${id}/${Date.now()}.jpg`;
if(status) status.textContent = "Subiendo a Supabase…";
const { error: uploadError } = await supabaseClient.storage
.from(STORAGE_BUCKET_PRODUCTOS)
.upload(ruta, blob, { contentType:"image/jpeg", cacheControl:"31536000", upsert:false });
if(uploadError) throw uploadError;
const { data: publicData } = supabaseClient.storage.from(STORAGE_BUCKET_PRODUCTOS).getPublicUrl(ruta);
const nuevaUrl = publicData?.publicUrl;
if(!nuevaUrl) throw new Error("Supabase no devolvió la URL pública de la foto.");
const urlAnterior = p.imagenUrl || "";
p.imagenUrl = nuevaUrl;
try{
await guardarProductoDB(p);
}catch(error){
p.imagenUrl = urlAnterior;
await supabaseClient.storage.from(STORAGE_BUCKET_PRODUCTOS).remove([ruta]);
throw error;
}
if(rutaAnterior){
supabaseClient.storage.from(STORAGE_BUCKET_PRODUCTOS).remove([rutaAnterior]).catch(() => {});
}
renderAdminProductos();
renderMenu();
mostrarConfirmacion("✓ Foto actualizada correctamente");
}catch(error){
console.error(error);
if(status) status.textContent = "Error: " + (error.message || error);
alert("No se pudo subir la foto: " + (error.message || error));
}finally{
if(input) input.value = "";
}
}
async function eliminarFotoProducto(id){
const p = PRODUCTOS.find(x => x.id === id);
if(!p || !p.imagenUrl) return;
if(!await confirmarAccion({
titulo:"Eliminar fotografía",
mensaje:`Se quitará la foto de "${p.nombre || "este producto"}" del menú.`,
confirmar:"Eliminar foto",
peligro:true,
icono:"📷"
})) return;
const urlAnterior = p.imagenUrl;
const rutaAnterior = rutaStorageDesdeUrl(urlAnterior);
try{
p.imagenUrl = "";
await guardarProductoDB(p);
if(rutaAnterior){
const { error } = await supabaseClient.storage.from(STORAGE_BUCKET_PRODUCTOS).remove([rutaAnterior]);
if(error) console.warn("La referencia se eliminó, pero no se pudo borrar el archivo viejo:", error);
}
renderAdminProductos();
renderMenu();
mostrarConfirmacion("✓ Foto eliminada");
}catch(error){
p.imagenUrl = urlAnterior;
alert("No se pudo eliminar la foto: " + (error.message || error));
}
}
