async function registrarGasto(){
const fecha = document.getElementById("gasto-fecha")?.value;
const categoria = document.getElementById("gasto-categoria")?.value || "Otros";
const descripcion = document.getElementById("gasto-descripcion")?.value.trim() || "";
const monto = Number(document.getElementById("gasto-monto")?.value) || 0;
const proveedor = document.getElementById("gasto-proveedor")?.value.trim() || "";
const formaPago = document.getElementById("gasto-pago")?.value || "";
const nota = document.getElementById("gasto-nota")?.value.trim() || "";
if(!fecha){
alert("Seleccioná la fecha del gasto.");
return;
}
if(!descripcion){
alert("Indicá una descripción para el gasto.");
document.getElementById("gasto-descripcion")?.focus();
return;
}
if(monto <= 0){
alert("El monto del gasto debe ser mayor que cero.");
document.getElementById("gasto-monto")?.focus();
return;
}
if(!await confirmarAccion({
titulo:"Registrar gasto",
mensaje:`${descripcion} · ${money(monto)} · ${categoria}`,
confirmar:"Registrar gasto",
icono:"₡"
})) return;
const gasto = {
id:idNuevo("gasto"),
fecha:new Date(fecha + "T12:00:00").toISOString(),
categoria,
descripcion,
monto,
proveedor,
formaPago,
nota
};
try{
await guardarGastoDB(gasto);
}catch(error){
alert("No se pudo registrar el gasto: " + (error.message || error));
return;
}
GASTOS.unshift(gasto);
mostrarConfirmacion(`✓ Gasto registrado: ${money(gasto.monto)}`);
document.getElementById("gasto-descripcion").value = "";
document.getElementById("gasto-monto").value = "";
document.getElementById("gasto-proveedor").value = "";
document.getElementById("gasto-nota").value = "";
contaMesSeleccionado = new Date(gasto.fecha).getMonth();
contaAnioSeleccionado = new Date(gasto.fecha).getFullYear();
renderContabilidad();
}
async function eliminarGasto(id){
const gasto = GASTOS.find(g => g.id === id);
if(!gasto) return;
if(!await confirmarAccion({
titulo:"Eliminar gasto",
mensaje:`"${gasto.descripcion}" por ${money(gasto.monto)} se eliminará de la contabilidad.`,
confirmar:"Eliminar gasto",
peligro:true,
icono:"!"
})) return;
try{
await eliminarGastoDB(id);
}catch(error){
alert("No se pudo eliminar el gasto: " + (error.message || error));
return;
}
GASTOS = GASTOS.filter(g => g.id !== id);
mostrarConfirmacion("✓ Gasto eliminado");
renderContabilidad();
}
