let promesaXLSX = null;
function asegurarXLSX(){
if(window.XLSX) return Promise.resolve(window.XLSX);
if(promesaXLSX) return promesaXLSX;
promesaXLSX = new Promise((resolve,reject) => {
const s = document.createElement("script");
s.src = "https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js";
s.async = true;
s.onload = () => window.XLSX ? resolve(window.XLSX) : reject(new Error("No se pudo inicializar Excel."));
s.onerror = () => {
s.remove();
const fallback=document.createElement("script");
fallback.src="https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js";
fallback.async=true;
fallback.onload=()=>window.XLSX ? resolve(window.XLSX) : reject(new Error("No se pudo inicializar Excel."));
fallback.onerror=()=>reject(new Error("No se pudo descargar la librería de Excel. Revisá la conexión e intentá de nuevo."));
document.head.appendChild(fallback);
};
document.head.appendChild(s);
}).catch(err => {
promesaXLSX = null;
throw err;
});
return promesaXLSX;
}
